patch:
diff --git a/tmp-repro/report.js b/tmp-repro/report.js
new file mode 100644
index 0000000..a9c9311
--- /dev/null
+++ b/tmp-repro/report.js
@@ -0,0 +1,9 @@
+/* eslint no-useless-assignment: "error" */
+
+// shows error
+[1, 2, 3].map(i => ++i);
+[1, 2, 3].map(i => --i);
+
+// no error
+[1, 2, 3].map(i => i + 1);
+[1, 2, 3].map(i => i - 1);
diff --git a/tmp-repro/repro.js b/tmp-repro/repro.js
new file mode 100644
index 0000000..6220d8f
--- /dev/null
+++ b/tmp-repro/repro.js
@@ -0,0 +1,32 @@
+"use strict";
+// Reproduction for: no-useless-assignment reports ++i / --i whose result is returned (eslint 9.28.0)
+const { RuleTester } = require("../lib/rule-tester");
+const rule = require("../lib/rules/no-useless-assignment");
+
+const ruleTester = new RuleTester();
+
+let failed = false;
+RuleTester.describe = (_name, fn) => fn();
+RuleTester.it = RuleTester.itOnly = (name, fn) => {
+	try {
+		fn();
+		console.log(`PASS ${name}`);
+	} catch (err) {
+		failed = true;
+		console.log(`FAIL ${name}\n  ${err.message.split("\n")[0]}`);
+	}
+};
+
+ruleTester.run("no-useless-assignment", rule, {
+	valid: [
+		// Reporter's expected-clean cases
+		"[1, 2, 3].map(i => ++i);",
+		"[1, 2, 3].map(i => --i);",
+		// Control from the report (already clean)
+		"[1, 2, 3].map(i => i + 1);",
+		"[1, 2, 3].map(i => i - 1);",
+	],
+	invalid: [],
+});
+
+process.exitCode = failed ? 1 : 0;
diff --git a/tmp-repro/variants.js b/tmp-repro/variants.js
new file mode 100644
index 0000000..56677e5
--- /dev/null
+++ b/tmp-repro/variants.js
@@ -0,0 +1,11 @@
+/* eslint no-useless-assignment: "error" */
+[1].map(i => ++i);                          // A arrow expr body, prefix
+[1].map(i => i++);                          // B arrow expr body, postfix
+[1].map(i => { return ++i; });              // C block body return
+function f1(i) { return ++i; }              // D function decl
+function f2(i) { foo(++i); }                // E passed as argument
+function f3(i) { const y = ++i; foo(y); }   // F result stored elsewhere
+function f4(i) { i += 1; return i; }        // G compound assign then read
+function f5(i) { return i += 1; }           // H compound assign as return value
+function f6(i) { return i = i + 1; }        // I plain assign as return value
+function f7() { let i = 0; return ++i; }    // J local let
